avatar.layer.shadowOpacity = 0.3
avatar.clipsToBounds = true        // ...and now the shadow is clipped away as well

// RIGHT: choose how the pixels fit, then where they stop
let image = UIImageView(image: photo)
image.contentMode = .scaleAspectFill   // fills the box, keeps the aspect ratio
image.clipsToBounds = true             // == layer.masksToBounds; crops the overflow
image.layer.cornerRadius = 24
image.layer.cornerCurve = .continuous  // the system squircle, not a circular arc

// A shadow and clipping cannot share a view — nest them
