card.layer.shadowOpacity = 0.3
card.layer.shadowRadius = 12
card.layer.shadowOffset = CGSize(width: 0, height: 4)
card.addSubview(image)                 // inner view clips, outer view casts

override func layoutSubviews() {
  super.layoutSubviews()
  // Both of these are in points, so they follow the size instead of leading it
  image.layer.cornerRadius = image.bounds.width / 2
  card.layer.shadowPath = UIBezierPath(roundedRect: card.bounds, cornerRadius: 24).cgPath
}

