  self.titleLabel.text = String(decoding: data!, as: UTF8.self)   // UIKit off-main
}.resume()

// RIGHT, callback style: hop back for the UI work only
URLSession.shared.dataTask(with: url) { data, _, _ in
  guard let data, let profile = try? JSONDecoder().decode(Profile.self, from: data) else { return }
  DispatchQueue.main.async { self.titleLabel.text = profile.name }   // decoding stayed off-main
}.resume()

// RIGHT, modern: UIKit is @MainActor, so the compiler enforces the rule
@MainActor
final class ProfileViewController: UIViewController {
  let titleLabel = UILabel()

  func load(_ url: URL) {
    Task {                                    // inherits the main actor
      let (data, _) = try await URLSession.shared.data(from: url)
      let profile = try JSONDecoder().decode(Profile.self, from: data)
      titleLabel.text = profile.name          // still on the main actor: legal
    }
  }
}

// The reverse trap: that Task runs ON the main actor, so heavy work in it janks.
// Push the work out, then come back for the view.
Task.detached(priority: .userInitiated) {
  let thumb = await renderThumbnail(from: fullSize)
  await MainActor.run { imageView.image = thumb }
}

// Drawing is safe off the main thread — this is the exception worth remembering
nonisolated func renderThumbnail(from image: UIImage) async -> UIImage {
  let size = CGSize(width: 120, height: 120)
  return UIGraphicsImageRenderer(size: size).image { _ in
    image.draw(in: CGRect(origin: .zero, size: size))
  }
}

final class CardViewController: UIViewController, UIGestureRecognizerDelegate {
  private let scrollView = UIScrollView()
  private let card = UIView()
  private var dragStart: CGPoint = .zero

  override func viewDidLoad() {
    super.viewDidLoad()

    let pan = UIPanGestureRecognizer(target: self, action: #selector(handlePan))
    pan.delegate = self                 // weak: keep the delegate alive yourself
    card.addGestureRecognizer(pan)

    let double = UITapGestureRecognizer(target: self, action: #selector(zoom))
    double.numberOfTapsRequired = 2
    let single = UITapGestureRecognizer(target: self, action: #selector(open))
    single.require(toFail: double)      // buys the double tap ~0.3s of delay for the single
    card.addGestureRecognizer(double)
    card.addGestureRecognizer(single)
  }

  @objc private func handlePan(_ g: UIPanGestureRecognizer) {
    switch g.state {
    case .began:
      dragStart = card.center           // capture once, then measure against it
    case .changed:
      let t = g.translation(in: view)
      card.center = CGPoint(x: dragStart.x, y: dragStart.y + t.y)
    case .ended, .cancelled:            // .cancelled matters as much as .ended
      settle(velocity: g.velocity(in: view).y)
    default:
      break
    }
  }

  // Coexist with the scroll view instead of cancelling it
  func gestureRecognizer(_ g: UIGestureRecognizer,
                         shouldRecognizeSimultaneouslyWith other: UIGestureRecognizer) -> Bool {
    other === scrollView.panGestureRecognizer
  }

  // Leave touches that landed on a control alone
  func gestureRecognizer(_ g: UIGestureRecognizer, shouldReceive touch: UITouch) -> Bool {
    !(touch.view is UIControl)
  }

  @objc private func zoom() {}
  @objc private func open() {}
  private func settle(velocity: CGFloat) {}
}

final class AgendaViewController: UIViewController {
  private let tableView = UITableView()
  private let header = UIView()
  private var didScrollToToday = false
  private var todayIndexPath = IndexPath(row: 0, section: 0)

  // WRONG: the view may not be in the hierarchy yet and bounds are stale,
  // so the offset lands somewhere else entirely
  override func viewWillAppear(_ animated: Bool) {
    super.viewWillAppear(animated)
    tableView.scrollToRow(at: todayIndexPath, at: .top, animated: false)
  }

  // WRONG: right numbers, wrong cardinality — this runs on every layout pass,
  // hence the flag everybody used to write
  override func viewDidLayoutSubviews() {
    super.viewDidLayoutSubviews()
    if !didScrollToToday {
      didScrollToToday = true
      tableView.scrollToRow(at: todayIndexPath, at: .top, animated: false)
    }
  }

  // RIGHT: once per appearance, in the hierarchy, bounds and traits final
  override func viewIsAppearing(_ animated: Bool) {
    super.viewIsAppearing(animated)
    tableView.scrollToRow(at: todayIndexPath, at: .top, animated: false)
    header.frame.size.height = view.bounds.width > 700 ? 220 : 140
  }

  override func viewDidAppear(_ animated: Bool) {
    super.viewDidAppear(animated)
    Analytics.track("agenda_shown")   // only here has the transition actually finished
  }
}

