final class BadgeView: UIView {
  override init(frame: CGRect) {
    super.init(frame: frame)

    // WRONG: resolved once, against whichever style happened to be current
    layer.borderColor = UIColor.separator.cgColor

    // RIGHT: resolve explicitly now...
    layer.borderColor = UIColor.separator.resolvedColor(with: traitCollection).cgColor

    // ...and again whenever that one trait changes (iOS 17+)
    registerForTraitChanges([UITraitUserInterfaceStyle.self]) { (self: Self, _: UITraitCollection) in
      self.layer.borderColor = UIColor.separator
        .resolvedColor(with: self.traitCollection).cgColor
    }
  }
  required init?(coder: NSCoder) { fatalError("use init(frame:)") }

  // Deprecated in iOS 17. The warning is easy to ignore and the symptom is silent.
  // override func traitCollectionDidChange(_ previous: UITraitCollection?) { }
}

