final class InboxViewController: UIViewController, UIAdaptivePresentationControllerDelegate {
  private weak var editor: EditorViewController?

  func showEditor(_ draft: Draft) {
    let editor = EditorViewController(draft: draft)
    let nav = UINavigationController(rootViewController: editor)
    nav.sheetPresentationController?.detents = [.medium(), .large()]
    nav.sheetPresentationController?.prefersGrabberVisible = true
    nav.presentationController?.delegate = self   // on the controller you present; weak
    self.editor = editor
    present(nav, animated: true)
    // The static equivalent of the delegate method below:
    // nav.isModalInPresentation = true           // the nav, not the editor inside it
  }

  // Block the swipe only while there is something to lose
  func presentationControllerShouldDismiss(_ controller: UIPresentationController) -> Bool {
    editor?.hasUnsavedChanges != true
  }

  // Called only when the swipe was refused — ask here, do not guess
  func presentationControllerDidAttemptToDismiss(_ controller: UIPresentationController) {
    let sheet = UIAlertController(title: "Discard this draft?", message: nil,
                                  preferredStyle: .actionSheet)
    sheet.addAction(UIAlertAction(title: "Discard", style: .destructive) { _ in
      self.dismiss(animated: true)
    })
    sheet.addAction(UIAlertAction(title: "Keep Editing", style: .cancel))
    controller.presentedViewController.present(sheet, animated: true)
  }

  // User-driven dismissal only: your own dismiss(animated:) never reaches this
  func presentationControllerDidDismiss(_ controller: UIPresentationController) {
    reloadInbox()
  }

  // iPad: a popover that has to become a sheet when the width goes compact
  func adaptivePresentationStyle(for controller: UIPresentationController,
                                 traitCollection: UITraitCollection) -> UIModalPresentationStyle {
    traitCollection.horizontalSizeClass == .compact ? .pageSheet : .none
  }

  private func reloadInbox() {}
}

final class RatingControl: UIControl {
  private let stars = UIStackView()
  var rating: Int = 0 {
    didSet {
      updateStars()
      accessibilityValue = "\(rating) out of 5"   // update where the state changes
    }
  }

  override init(frame: CGRect) {
    super.init(frame: frame)
    addSubview(stars)

    // One element: VoiceOver stops walking the five image views inside
    isAccessibilityElement = true
    accessibilityLabel = "Rating"                 // not "star.fill", not "button"
    accessibilityValue = "\(rating) out of 5"
    accessibilityTraits = .adjustable             // promises the two methods below
    accessibilityIdentifier = "rating"            // UI tests only; never spoken
  }
  required init?(coder: NSCoder) { fatalError("use init(frame:)") }

  // .adjustable turns a swipe up or down into these
  override func accessibilityIncrement() {
    rating = min(rating + 1, 5)
    sendActions(for: .valueChanged)
  }

  override func accessibilityDecrement() {
    rating = max(rating - 1, 0)
    sendActions(for: .valueChanged)
  }

  private func updateStars() {}
}

